                NL.css("sh-maint", ".sy-fleet-row button[data-nl2-shmt],.sy-fleet-row[data-nl2-shmt] .sy-fleet-dmg,.sy-fleet-row[data-nl2-shmt] .sy-fleet-damaged{display:none!important}");
                const SH_DOCK_KEY = "orbital_shipyard";
