                const CATS = [["resource", "Resource"], ["energy", "Energy"], ["utility", "Utility"], ["military", "Military"], ["defense", "Defense"]];
                const esc = (v) => String(v).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;" }[c]));
