        NL.feature({
            id: "mo-storage",
            set: "Moons",
            name: "Storage badge",
            desc: "MO-008: the Moons menu badge also counts each produced moon resource at 75% of storage or more, with the resource and % on hover.",
            init() {
                const RES = [["ore", "Ore"], ["silicates", "Silicates"], ["hydrogen", "Hydrogen"], ["alloys", "Alloys"], ["cryoIce", "Cryo-Ice"], ["quantumDust", "Quantum Dust"], ["plasmaCore", "Plasma Core"], ["bioExtract", "Bio-Extract"], ["darkMatter", "Dark Matter"], ["antimatter", "Antimatter"]];
                const BASE = ["ore", "silicates", "hydrogen", "alloys"];
                const clean = (t) => String(t == null ? "" : t).replace(/\s*\[[^\]]*\]\s*$/, "").trim();
                const seen = {};
                const names = {};
                const shown = new Set();
                const put = (id, v) => { if (id == null)
                    return; const k = String(id); if (!seen[k] || seen[k].at <= v.at)
                    seen[k] = v; };
                const capOf = (src, k) => {
                    if (src == null)
                        return 0;
                    if (typeof src === "object")
                        return moN(src[k] != null ? src[k] : BASE.includes(k) ? 0 : src.rare);
                    return moN(src);
                };
                NL.onData(/^\/api\/moons\/\d+$/, (p, d, at) => {
                    const s = d && d.resourceSnapshot;
                    if (!s || !s.resources)
                        return;
                    const t = Date.parse(s.resourcesUpdatedAt || s.serverNow) || at, cap = {};
                    for (const [k] of RES)
                        cap[k] = capOf(s.storage, k);
                    put(p.split("/").pop(), { at: Math.min(t, at), name: d.moon && d.moon.name, res: s.resources, rate: s.productionRates || {}, cap });
                    check();
                });
                NL.onData(/^\/api\/command-center\/empire-resources/, (p, d, at) => {
                    const t = Math.min(Date.parse(d && d.serverNow) || at, at);
                    for (const m of (d && d.moons) || []) {
                        if (!m || m.id == null)
                            continue;
                        const res = {}, rate = {}, cap = {};
                        for (const [k] of RES) {
                            res[k] = m[k];
                            rate[k] = m[k + "Rate"];
                            cap[k] = m[k + "Storage"] != null ? moN(m[k + "Storage"]) : BASE.includes(k) ? capOf(m.storage, k) : moN(m.rareResourceStorage != null ? m.rareResourceStorage : capOf(m.storage, k));
                        }
                        put(m.id, { at: t, name: m.name, res, rate, cap });
                    }
                    check();
                });
                NL.onData(/^\/api\/planets\/activity-summary$/, (p, d) => {
                    for (const pl of (d && d.planets) || [])
                        for (const m of pl.moons || [])
                            if (m && m.id != null && m.name)
                                names[m.id] = clean(m.name);
                    check();
                });
                let inbound = new Set();
                if (NL.badgeRows)
                    setInterval(() => check(), 60000);
                NL.onData(/^\/api\/fleet\/missions(\?|$)/, (p, d) => {
                    inbound = new Set(((d && d.missions) || []).filter((m) => m && m.targetMoonId != null && m.status === "outbound").map((m) => String(m.targetMoonId)));
                    check();
                });
                function check() {
                    const now = Date.now(), live = new Set(), full = new Set();
                    for (const [id, v] of Object.entries(seen)) {
                        const name = names[id] || clean(v.name);
                        if (!name)
                            continue;
                        const hrs = Math.max(0, now - v.at) / 3600000, hits = [];
                        const rules = !!(NL.badgeReg && NL.badgeReg.storageRules), warn = rules ? 0.9 : 0.75;
                        for (const [k, label] of RES) {
                            if (rules && (k === "darkMatter" || k === "quantumDust"))
                                continue;
                            const r = moN(v.rate[k]), c = moN(v.cap[k]);
                            if (c <= 0)
                                continue;
                            const pct = Math.min(c, moN(v.res[k]) + Math.max(0, r) * hrs) / c;
                            if (NL.badgeRows && pct >= 1 && (r > 0 || rules)) {
                                full.add(id);
                                hits.push(label + " 100%");
                            }
                            else if (r > 0 && pct >= warn && !(NL.badgeRows && inbound.has(id)))
                                hits.push(label + " " + Math.floor(pct * 100) + "%");
                        }
                        if (NL.moThr && NL.moThr.on() === true) {
                            hits.length = 0;
                            full.delete(id);
                        }
                        live.add(name);
                        moBadgeSet("storage", name, hits);
                        if (hits.length)
                            shown.add(name);
                        else
                            shown.delete(name);
                    }
                    for (const n of [...shown])
                        if (!live.has(n)) {
                            moBadgeSet("storage", n, []);
                            shown.delete(n);
                        }
                    const sf = NL.storageFull || (NL.storageFull = {}), key = [...full].sort().join();
                    if ((sf.moons ? [...sf.moons].sort().join() : "") !== key) {
                        sf.moons = full;
                        if (NL.navBadgeChanged)
                            NL.navBadgeChanged("/fleet");
                    }
                }
            },
        });
